) {
  const chunk = buildStructuredRecordChunk(
    record.recordType,
    record.id,
    [
      `Finance record: ${record.id}`,
      `Type: ${record.recordType}`,
      `Voyage: ${record.voyageId}`,
      `Vessel: ${record.vesselName}`,
      record.amount ? `Amount: ${record.currency ?? ""} ${record.amount}` : undefined,
